import{_ as a,o as i,c as e,ag as n}from"./chunks/framework.DzGOF12C.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"computer/System-Programming/01. WSL Ubuntu 설치.md","filePath":"computer/System-Programming/01. WSL Ubuntu 설치.md"}'),l={name:"computer/System-Programming/01. WSL Ubuntu 설치.md"};function t(p,s,d,r,h,o){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>ELEC462 시스템 프로그래밍 실습은 Ubuntu 24.04 환경을 전제로 함. Windows에서는 WSL(Windows Subsystem for Linux)을 쓰는 걸 강의에서 권장.</p><p>Windows에서 Ubuntu를 쓰는 방법은 여러 가지:</p><ul><li><strong>WSL</strong> — Windows 안에서 리눅스 커널이 Hyper-V 기반 경량 VM으로 돌아가는 방식. 강의 권장 방법</li><li><strong>가상머신(VM)</strong> — VMware Workstation Player 등으로 통째로 가상화</li><li><strong>원격 리눅스 서버</strong> — GCP/AWS 프리티어에 SSH 접속</li><li><strong>듀얼부팅</strong></li></ul><h2 id="wsl-설치-손상-문제-해결" tabindex="-1">WSL 설치 손상 문제 해결 <a class="header-anchor" href="#wsl-설치-손상-문제-해결" aria-label="Permalink to &quot;WSL 설치 손상 문제 해결&quot;">​</a></h2><p><code>wsl --list --online</code> 실행 시 다음 오류 발생:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>wsl: WSL 설치가 손상된 것 같습니다</span></span>
<span class="line"><span>오류 코드: Wsl/CallMsi/Install/REGDB_E_CLASSNOTREG</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>wsl.exe</code>는 Windows에 기본 내장되어 있어서 따로 설치한 적이 없어도 존재하는데, COM 클래스 등록이 깨져서 발생하는 문제였음. 관리자 권한 터미널에서:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wsl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --update</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>실행하니 &quot;아무 키나 눌러 복구&quot; 프롬프트가 뜨고, 복구 진행 후 정상 버전(2.7.13)으로 업데이트되면서 해결됨.</p><p>(만약 이걸로 안 됐다면 다음 단계로 WSL 기능을 껐다 켜는 방법이 있음:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dism.exe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /online</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /disable-feature</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /featurename:Microsoft-Windows-Subsystem-Linux</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /norestart</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dism.exe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /online</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /enable-feature</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /featurename:Microsoft-Windows-Subsystem-Linux</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /all</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /norestart</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>재부팅 후 재시도.)</p><h2 id="ubuntu-24-04-설치" tabindex="-1">Ubuntu 24.04 설치 <a class="header-anchor" href="#ubuntu-24-04-설치" aria-label="Permalink to &quot;Ubuntu 24.04 설치&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wsl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Ubuntu-24.04</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wsl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --set-default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Ubuntu-24.04</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>첫 실행 시 유닉스 사용자 계정(이름/비밀번호)을 새로 만들어야 함 — Windows 계정과는 무관한 별개의 리눅스 계정.</p><p>버전 확인:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/issue</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Ubuntu 24.04.4 LTS</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="wsl과-windows의-관계" tabindex="-1">WSL과 Windows의 관계 <a class="header-anchor" href="#wsl과-windows의-관계" aria-label="Permalink to &quot;WSL과 Windows의 관계&quot;">​</a></h2><p>WSL2는 듀얼부팅과 달리, Windows가 켜진 상태에서 리눅스 커널이 Hyper-V 기반 VM으로 백그라운드에 같이 돌아가는 구조. 물리적으로는 커널과 파일시스템이 분리된 두 시스템이지만, <code>wsl</code> 명령 한 번으로 몇 초 만에 오가며 Windows 탐색기(<code>\\\\wsl$\\</code>)에서도 리눅스 파일에 접근 가능해서 듀얼부팅보다 훨씬 통합되어 있음.</p><ul><li>리눅스 파일시스템은 <code>.vhdx</code> 가상 디스크 파일 안에 통째로 들어있음 (직접 건드리면 안 되고 <code>wsl</code> 명령이나 <code>\\\\wsl$\\</code> 경로로만 접근)</li><li><code>/mnt/c/</code>가 곧 Windows의 <code>C:\\</code> — WSL에서 Windows 파일에 접근할 때 씀</li><li>실습 파일은 <code>/mnt/c/...</code>가 아니라 리눅스 홈 디렉토리(<code>~</code>, 즉 <code>/home/&lt;user&gt;</code>)에 두는 게 속도/권한 면에서 유리</li></ul><h2 id="실습-폴더-세팅-vs-code-연결" tabindex="-1">실습 폴더 세팅 &amp; VS Code 연결 <a class="header-anchor" href="#실습-폴더-세팅-vs-code-연결" aria-label="Permalink to &quot;실습 폴더 세팅 &amp; VS Code 연결&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> elec462</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> elec462</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>VS Code(Windows에 설치된 것) + <strong>WSL 확장</strong> 설치 후, WSL 셸에서:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">code</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>최초 실행 시 리눅스 쪽에 VS Code Server를 자동 설치함 (한 번만, 정상 과정). 완료되면 VS Code 좌측 하단에 <code>WSL: Ubuntu-24.04</code> 배지가 뜨는 것으로 연결 확인.</p><p>구조: Windows의 VS Code가 화면(GUI)만 담당하고, 실제 파일 읽기/터미널 실행/확장 동작은 리눅스 쪽 VS Code Server가 담당하는 방식.</p><h2 id="컴파일-도구-설치" tabindex="-1">컴파일 도구 설치 <a class="header-anchor" href="#컴파일-도구-설치" aria-label="Permalink to &quot;컴파일 도구 설치&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-essential</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gdb</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>build-essential</code>에 gcc, make 등 포함.</p><h2 id="참고-nvmevirt는-wsl과-안-맞음" tabindex="-1">참고: NVMeVirt는 WSL과 안 맞음 <a class="header-anchor" href="#참고-nvmevirt는-wsl과-안-맞음" aria-label="Permalink to &quot;참고: NVMeVirt는 WSL과 안 맞음&quot;">​</a></h2><p>같은 시스템 프로그래밍 관련 실험이라도 <a href="https://github.com/snu-csl/nvmevirt" target="_blank" rel="noreferrer">NVMeVirt</a> 같은 커널 모듈 프로젝트는 WSL2로 돌리기 어려움:</p><ul><li>WSL2는 Microsoft가 자체 빌드한 특수 커널이라 <code>apt</code>로 받는 일반 커널 헤더가 없음 — 모듈을 빌드하려면 WSL2 커널 소스를 직접 받아 빌드해야 함</li><li>부팅 시 메모리 영역을 예약(<code>memmap=</code>)해야 하는 요구사항도 WSL2에서는 지원이 불확실</li><li>이런 커널 모듈 실습은 VM(VMware/VirtualBox)이나 베어메탈 리눅스에서 하는 게 안전</li></ul>`,33)])])}const k=a(l,[["render",t]]);export{u as __pageData,k as default};
